  job_txt  text := 'backfill:michelin-2025-france-archive | item 4 (Ben, Nov 1 15:50 ET "N1, P2, Q1, R1, S1"; 19:02 ET "W1, x1, U3"): Michelin Guide France 2025 (with Monaco) stars from web.archive.org | 13 existing 2025 star rows get the source_url; 580 rows inserted (One Star:486,Three Stars:31,Two Stars:76 in all 593) | source_url = https://web.archive.org/web/20250331212340id_/https://guide.michelin.com/fr/fr/article/michelin-guide-ceremony/guide-michelin-france-2025-la-liste-complete-des-etoiles | relay docs/fr-2025-build/relay-fr-2025-archive-20250331.txt sha256 2c643dc5...cd4c1a; card links links-fr-2025-archive-20250331.txt sha256 fa612061...0b1b18 | counts = article 654 starred (31/81/542) | ceremony Metz, Mar 31 2025 | match: card link = Michelin card of an existing award row (543); venue id, 2025 row: 38 -> ve_492797f355; 48 -> ve_070ced1e07; 50 -> ve_95253d6c9e; 187 -> ve_68ad93cad4; 386 -> ve_36022e9b0a; 391 -> ve_72f235f057; 395 -> ve_54915423d1; 421 -> ve_3bb332e0ec; 428 -> ve_b2c6b30c6e; 454 -> ve_1fa87032fe; 467 -> ve_63aed2ba90; 468 -> ve_ef978b8a59; 613 -> ve_e1bffb1188; venue id, same name 2026 row: 68 -> ve_5f2aaf2e90; 71 -> ve_f075d9ec6b; 109 -> ve_20abced354; 124 -> ve_6155d4ebdf; 175 -> ve_3081a1a5ed; 179 -> ve_7afa7aaf3e; 200 -> ve_de5b455b8d; 201 -> ve_dc8cab89a0; 251 -> ve_4a7ca97f2c; 330 -> ve_62d149aafe; 425 -> ve_2a8ec4ed1a; 519 -> ve_811a48504e; 531 -> ve_5ee7e8ac6f; 554 -> ve_639bbbc461; 563 -> ve_c8f1322fa5; 590 -> ve_804fcbc58a; 608 -> ve_5d5203048a; 614 -> ve_d61dd48136; 615 -> ve_24b9c243a7; 647 -> ve_fa7fd51058; W1 near-name, same 2026 card: 59 -> ve_62593f532b; 82 -> ve_755bf8d6ea; 103 -> ve_4e77c0295c; 128 -> ve_b5e82c5a77; 258 -> ve_9be720211b; 267 -> ve_dd6de25c33; 295 -> ve_0d0e52e950; 314 -> ve_634228e9d5; 323 -> ve_1dd2e9c45c; 397 -> ve_3735c86fab; 399 -> ve_bf76d7e634; 449 -> ve_12b49f155d; 513 -> ve_1462089111; 529 -> ve_77e6e37fab; 589 -> ve_74b0053f51; 616 -> ve_c89c116860; X1 name-only: 375 -> ve_75f04d40b5 | Q1 skipped (no venue, rejected candidate, X1 skip): Château de Beaulieu - Christophe Dufossé; Michel Kayser - Restaurant Alexandre; Palais Royal Restaurant; Maison Ronan Kervarrec; La Pyramide - Maison Henriroux; Auberge de l''Abbaye; Auberge de la Tour; Flaveurs; Le Fantin Latour - Stéphane Froidevaux; Le P''tit Polyte; L''Atelier Yssoirien; Le Gourmet de Sèze; La Sommelière; Les Terrasses de Lyon; Vincent Favre Félix; Frédéric Molina au Moulin de Léré; L''Empreinte; Pierre; Le Valucien - Château de Vault-de-Lugny; Le Brittany; Le Pourquoi Pas; Au 14 Février; La Vieille Tour; Le Lièvre Gourmand; La Cheneaudière - Le Feuillage; Thierry Schwartz - Le Restaurant; Auberge au Bœuf; La Table - Hôtel Clarance; La Dame de Pic; Yam''Tcha; Helen; Le Chiberta; L''Écrin; Le Faham by Kelly Rangama; Numéro 3; Le Village Tomohiro; Ducasse au Château de Versailles - Le Grand Contrôle; Pavyllon, un restaurant de Yannick Alléno, Monte-Carlo; Les Sources de Fontbelle; L''Aquarelle; L''Hysope; Michel Trama; Les Rosiers; La Table des Frères Ibarboure; Le Moulin de la Gorce; Ô Saveurs; The Marcel; Le Pont de l''Ouysse; La Coopérative - Domaine Riberach; Le 1201 - Abbaye de Villeneuve; Fontevraud Le Restaurant; Le Figuier de Saint-Esprit; Pure & V; Maison Hache; Hélène Darroze à Villa La Coste; Restaurant de Tourrel; L''Arbre au Soleil; Récif; La Closerie; La Mirande; La Mère Germaine | U3: 2025 Green Stars not loaded (no full list found; les-etoiles-vertes-du-guide-michelin-2025 lists 10 new only) | 2025 Bibs: no full list (N1), no change | plan md5 2076638fcc73bcfc3c8ab74b4a373461';
  pj jsonb; rj jsonb;
  cnt int; num int; txt text;
  aud_max bigint; aud_n bigint; led_max bigint; led_n bigint;
BEGIN
  pj := plan_txt::jsonb;

  -- 1. Plan guards
  SELECT md5(string_agg((e->>0) || '|' || (e->>1) || '|' || (e->>2) || '|' || (e->>3), E'\n' ORDER BY (e->>0)::int)), count(*)
    INTO txt, cnt FROM jsonb_array_elements(pj) e;
  IF txt <> '2076638fcc73bcfc3c8ab74b4a373461' OR cnt <> 593 THEN RAISE EXCEPTION 'plan md5 % / rows % (expected 2076638fcc73bcfc3c8ab74b4a373461 / 593)', txt, cnt; END IF;

WITH p AS (SELECT (e->>0)::int seq, e->>1 cat, e->>2 slug, nullif(e->>3, '') use_vid FROM jsonb_array_elements(pj) e),
  sl AS (SELECT DISTINCT lower(substring(split_part(a.source_url, '?', 1) from '/restaurant/([^/]+)/?$')) slug, a.venue_id
           FROM awards a JOIN venues v ON v.id = a.venue_id JOIN cities c ON c.id = v.city_id
          WHERE a.source_id = 'michelin' AND a.source_url ~ '/restaurant/' AND c.country_iso IN ('FR', 'MC')),
  t1 AS (SELECT p.seq, count(*) n, min(sl.venue_id) vid FROM p JOIN sl ON sl.slug = p.slug GROUP BY p.seq),
  r AS (SELECT p.seq, p.cat,
          CASE WHEN p.use_vid IS NOT NULL THEN p.use_vid WHEN t1.n = 1 THEN t1.vid END vid,
          CASE WHEN p.use_vid IS NOT NULL THEN 'use' WHEN t1.n = 1 THEN 'card' WHEN t1.n > 1 THEN 'multi' ELSE 'none' END how
        FROM p LEFT JOIN t1 USING (seq))
  SELECT jsonb_agg(jsonb_build_array(seq, cat, vid, how) ORDER BY seq) INTO rj FROM r;

  SELECT count(*) FILTER (WHERE vid IS NULL), md5(string_agg(seq || ':' || coalesce(vid, '-'), ',' ORDER BY seq))
    INTO cnt, txt FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) d;
  IF cnt <> 0 THEN RAISE EXCEPTION 'rows with no venue: %', cnt; END IF;
  IF txt <> '84c12d3f3959d8b6b7cc4795419b61dc' THEN RAISE EXCEPTION 'seq:venue md5 % (expected 84c12d3f3959d8b6b7cc4795419b61dc)', txt; END IF;
  SELECT count(*) INTO cnt FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) d JOIN venues v ON v.id = d.vid JOIN cities c ON c.id = v.city_id
   WHERE c.country_iso IN ('FR', 'MC');
  IF cnt <> 593 THEN RAISE EXCEPTION 'venues in FR/MC % (expected 593)', cnt; END IF;
  SELECT count(DISTINCT vid) INTO cnt FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) d;
  IF cnt <> 593 THEN RAISE EXCEPTION 'distinct venues % (expected 593)', cnt; END IF;

  SELECT count(*), md5(string_agg(a.id::text, ',' ORDER BY a.id)) INTO cnt, txt FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) r JOIN awards a
    ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat
   WHERE a.source_url IS NULL AND a.rank IS NULL AND a.distinction IS NULL;
  IF cnt <> 13 OR txt <> 'f7e9c501fa6eccf9f369844bde2dfd58' THEN RAISE EXCEPTION 'existing 2025 rows % / ids md5 % (expected 13 / f7e9c501fa6eccf9f369844bde2dfd58)', cnt, txt; END IF;
  SELECT count(*) INTO cnt FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) r JOIN awards a
    ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat;
  IF cnt <> 13 THEN RAISE EXCEPTION 'all existing 2025 rows on the plan % (expected 13)', cnt; END IF;
  SELECT count(*) INTO cnt FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) r JOIN awards a ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025
   WHERE a.category IN ('Three Stars', 'Two Stars', 'One Star') AND a.category <> r.cat;
  IF cnt <> 0 THEN RAISE EXCEPTION 'venues with a different 2025 star row: %', cnt; END IF;
  SELECT md5(string_agg(id::text, ',' ORDER BY id)) INTO txt FROM awards WHERE id IN (1648,1824,1826,4402,4748,5885,6463,7220,7233,7241,7250,7270,8926);
  IF txt <> 'f7e9c501fa6eccf9f369844bde2dfd58' THEN RAISE EXCEPTION 'existing id list md5 % (expected f7e9c501fa6eccf9f369844bde2dfd58)', txt; END IF;

  -- 2. Counts before (read Nov 2 00:08:49 UTC)
  SELECT count(*), max(id) INTO cnt, num FROM awards;
  IF cnt <> 23784 OR num <> 30723 THEN RAISE EXCEPTION 'awards before % / max % (expected 23784 / 30723)', cnt, num; END IF;
  SELECT count(*) INTO cnt FROM awards WHERE source_id = 'michelin';
                                                IF cnt <> 10080 THEN RAISE EXCEPTION 'Michelin awards before % (expected 10080)', cnt; END IF;
  SELECT count(*) INTO cnt FROM awards WHERE source_id = 'michelin' AND year = 2025;
                                                IF cnt <> 3704 THEN RAISE EXCEPTION 'Michelin 2025 before % (expected 3704)', cnt; END IF;
  SELECT count(*) INTO cnt FROM awards WHERE source_id = 'michelin' AND year = 2025 AND source_url IS NULL;
                                                IF cnt <> 3237 THEN RAISE EXCEPTION 'Michelin 2025 no URL before % (expected 3237)', cnt; END IF;
  SELECT count(*) INTO cnt FROM awards WHERE source_id = 'michelin' AND year = 2025 AND category = 'Green Star';
                                                IF cnt <> 31 THEN RAISE EXCEPTION 'Green Star 2025 before % (expected 31)', cnt; END IF;
  SELECT count(*) INTO cnt FROM awards a JOIN venues v ON v.id = a.venue_id JOIN cities c ON c.id = v.city_id
   WHERE a.source_id = 'michelin' AND a.year = 2025 AND c.country_iso IN ('FR', 'MC');
                                                IF cnt <> 20 THEN RAISE EXCEPTION 'FR/MC Michelin 2025 before % (expected 20)', cnt; END IF;
  SELECT count(*) INTO cnt FROM venues;         IF cnt <> 11299 THEN RAISE EXCEPTION 'venues before % (expected 11299)', cnt; END IF;
  SELECT count(*) INTO cnt FROM slugs;          IF cnt <> 13002 THEN RAISE EXCEPTION 'slugs before % (expected 13002)', cnt; END IF;
  SELECT count(*) INTO cnt FROM cities;         IF cnt <> 3260 THEN RAISE EXCEPTION 'cities before % (expected 3260)', cnt; END IF;
  SELECT sum(venues_count) INTO cnt FROM cities; IF cnt <> 10934 THEN RAISE EXCEPTION 'cities.venues_count sum before % (expected 10934)', cnt; END IF;
  SELECT count(*), max(id) INTO led_n, led_max FROM source_capture_ledger;
  IF led_n <> 162 OR led_max <> 214 THEN RAISE EXCEPTION 'ledger before % / max % (expected 162 / 214)', led_n, led_max; END IF;
  SELECT count(*), max(id) INTO aud_n, aud_max FROM audit_log;
  IF aud_n <> 116708 OR aud_max <> 122220 THEN RAISE EXCEPTION 'audit_log before % / max % (expected 116708 / 122220)', aud_n, aud_max; END IF;

  -- 3. Write
  UPDATE awards a SET source_url = arch_s
    FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) r
   WHERE a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat
     AND a.source_url IS NULL AND a.rank IS NULL AND a.distinction IS NULL;
  GET DIAGNOSTICS cnt = ROW_COUNT; IF cnt <> 13 THEN RAISE EXCEPTION 'award rows updated % (expected 13)', cnt; END IF;

  INSERT INTO awards (venue_id, source_id, year, rank, category, distinction, source_url)
  SELECT r.vid, 'michelin', 2025, NULL, r.cat, NULL, arch_s FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) r
   WHERE NOT EXISTS (SELECT 1 FROM awards a WHERE a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat)
   ORDER BY r.seq;
  GET DIAGNOSTICS cnt = ROW_COUNT; IF cnt <> 580 THEN RAISE EXCEPTION 'award rows inserted % (expected 580)', cnt; END IF;

  INSERT INTO source_capture_ledger (publisher, field_type, items, job) VALUES ('michelin', 'award', 593, job_txt);
  GET DIAGNOSTICS cnt = ROW_COUNT; IF cnt <> 1 THEN RAISE EXCEPTION 'ledger rows inserted % (expected 1)', cnt; END IF;

  -- 4. Post-checks
  SELECT count(*) INTO cnt FROM awards;         IF cnt <> 24364 THEN RAISE EXCEPTION 'awards after % (expected 24364)', cnt; END IF;
  SELECT count(*) INTO cnt FROM awards WHERE source_id = 'michelin';
                                                IF cnt <> 10660 THEN RAISE EXCEPTION 'Michelin awards after % (expected 10660)', cnt; END IF;
  SELECT count(*) INTO cnt FROM awards WHERE source_id = 'michelin' AND year = 2025;
                                                IF cnt <> 4284 THEN RAISE EXCEPTION 'Michelin 2025 after % (expected 4284)', cnt; END IF;
  SELECT count(*) INTO cnt FROM awards WHERE source_id = 'michelin' AND year = 2025 AND source_url IS NULL;
                                                IF cnt <> 3224 THEN RAISE EXCEPTION 'Michelin 2025 no URL after % (expected 3224)', cnt; END IF;
  SELECT count(*) INTO cnt FROM awards WHERE source_id = 'michelin' AND year = 2025 AND category = 'Green Star';
                                                IF cnt <> 31 THEN RAISE EXCEPTION 'Green Star 2025 after % (expected 31)', cnt; END IF;
  SELECT string_agg(category || ':' || num_cat, ',' ORDER BY category), sum(num_cat) INTO txt, cnt FROM (
    SELECT a.category, count(*) num_cat FROM awards a
     WHERE a.source_id = 'michelin' AND a.year = 2025 AND a.rank IS NULL AND a.distinction IS NULL AND a.source_url = arch_s
     GROUP BY a.category) g;
  IF cnt <> 593 OR txt <> 'One Star:486,Three Stars:31,Two Stars:76'
    THEN RAISE EXCEPTION 'France Michelin 2025 with the archive URL % / % (expected 593 / One Star:486,Three Stars:31,Two Stars:76)', cnt, txt; END IF;
  SELECT count(*) INTO cnt FROM awards a JOIN venues v ON v.id = a.venue_id JOIN cities c ON c.id = v.city_id
   WHERE a.source_id = 'michelin' AND a.year = 2025 AND c.country_iso IN ('FR', 'MC');
                                                IF cnt <> 600 THEN RAISE EXCEPTION 'FR/MC Michelin 2025 after % (expected 600)', cnt; END IF;
  SELECT md5(string_agg(r.seq || ':' || a.venue_id, ',' ORDER BY r.seq)) INTO txt
    FROM (SELECT (e->>0)::int seq, e->>1 cat, e->>2 vid, e->>3 how FROM jsonb_array_elements(rj) e) r JOIN awards a ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat
     AND a.source_url = arch_s;
  IF txt <> '84c12d3f3959d8b6b7cc4795419b61dc' THEN RAISE EXCEPTION 'seq:venue md5 after % (expected 84c12d3f3959d8b6b7cc4795419b61dc)', txt; END IF;
  SELECT count(*) INTO cnt FROM venues;         IF cnt <> 11299 THEN RAISE EXCEPTION 'venues changed: %', cnt; END IF;
  SELECT count(*) INTO cnt FROM slugs;          IF cnt <> 13002 THEN RAISE EXCEPTION 'slugs changed: %', cnt; END IF;
  SELECT count(*) INTO cnt FROM cities;         IF cnt <> 3260 THEN RAISE EXCEPTION 'cities changed: %', cnt; END IF;
  SELECT sum(venues_count) INTO cnt FROM cities; IF cnt <> 10934 THEN RAISE EXCEPTION 'cities.venues_count sum changed: %', cnt; END IF;

  SELECT count(*) INTO cnt FROM source_capture_ledger;
  IF cnt <> 163 THEN RAISE EXCEPTION 'ledger after % (expected 163)', cnt; END IF;
  SELECT count(*) INTO cnt FROM source_capture_ledger
   WHERE id > led_max AND publisher = 'michelin' AND field_type = 'award' AND items = 593 AND job = job_txt;
  IF cnt <> 1 THEN RAISE EXCEPTION 'new ledger row not found'; END IF;

  SELECT count(*) INTO cnt FROM audit_log WHERE id > aud_max;
  IF cnt <> 593 THEN RAISE EXCEPTION 'audit rows this transaction % (expected 593)', cnt; END IF;
  SELECT count(*) INTO cnt FROM audit_log al JOIN awards a ON a.id::text = al.row_pk
   WHERE al.id > aud_max AND al.table_name = 'awards' AND al.action = 'INSERT' AND al.old_row IS NULL
     AND a.source_id = 'michelin' AND a.year = 2025 AND al.new_row->>'source_url' = arch_s;
  IF cnt <> 580 THEN RAISE EXCEPTION 'audit INSERT rows % (expected 580)', cnt; END IF;
  SELECT count(*) INTO cnt FROM audit_log al
   WHERE al.id > aud_max AND al.table_name = 'awards' AND al.action = 'UPDATE'
     AND al.old_row->>'source_url' IS NULL AND al.new_row->>'source_url' = arch_s
     AND (al.old_row - 'source_url') = (al.new_row - 'source_url');
  IF cnt <> 13 THEN RAISE EXCEPTION 'audit UPDATE rows (source_url only) % (expected 13)', cnt; END IF;
END
$do$;
COMMIT;
